# helper used by the billing job
def invoice_total(items, vat_rate=0.19):
    net = sum(qty * price for qty, price in items)
    vat = round(net * vat_rate, 2)
    return {"net": round(net, 2), "vat": vat, "gross": round(net + vat, 2)}

if __name__ == "__main__":
    print(invoice_total([(2, 49.90), (1, 120.00)]))   # sample data only
